#include <iostream>
#include <string>
#include <vector>
class MyClass {
public:
  std::string data;
  MyClass(std::string s) : data(std::move(s)) {}  // Constructor taking string by value
  MyClass(MyClass&& other) : data(std::move(other.data)) { other.data = ""; } //Move constructor
  MyClass& operator=(MyClass&& other) {
    if (this != &other) {
      data = std::move(other.data);
      other.data = "";
    }
    return *this;
  }
  ~MyClass() { std::cout << "Destructor called for: " << data << std::endl; }
};
int main() {
  MyClass a("Hello");
  MyClass b = std::move(a); // Move assignment
  MyClass c{"World"};
  c = std::move(b); // Move assignment
  return 0;
}
